import{_ as o,r as a,o as p,c as l,e as s,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Form Controller - October CMS - 3.x","titleTemplate":false,"description":"Adds form management features to any backend page.","frontmatter":{"subtitle":"Adds form management features to any backend page."},"headers":[{"level":2,"title":"Configuring the Form Behavior","slug":"configuring-the-form-behavior","link":"#configuring-the-form-behavior","children":[{"level":3,"title":"Create Page","slug":"create-page","link":"#create-page","children":[]},{"level":3,"title":"Update Page","slug":"update-page","link":"#update-page","children":[]},{"level":3,"title":"Preview Page","slug":"preview-page","link":"#preview-page","children":[]},{"level":3,"title":"Custom Messages","slug":"custom-messages","link":"#custom-messages","children":[]},{"level":3,"title":"Restricting with Permissions","slug":"restricting-with-permissions","link":"#restricting-with-permissions","children":[]}]},{"level":2,"title":"Defining Form Fields","slug":"defining-form-fields","link":"#defining-form-fields","children":[]},{"level":2,"title":"Form Views","slug":"form-views","link":"#form-views","children":[{"level":3,"title":"Create View","slug":"create-view","link":"#create-view","children":[]},{"level":3,"title":"Update View","slug":"update-view","link":"#update-view","children":[]},{"level":3,"title":"Preview View","slug":"preview-view","link":"#preview-view","children":[]}]},{"level":2,"title":"Form Designs","slug":"form-designs","link":"#form-designs","children":[{"level":3,"title":"Display Modes","slug":"display-modes","link":"#display-modes","children":[]},{"level":3,"title":"Popup Display Mode","slug":"popup-display-mode","link":"#popup-display-mode","children":[]}]},{"level":2,"title":"Extending Form Behavior","slug":"extending-form-behavior","link":"#extending-form-behavior","children":[{"level":3,"title":"Extending the Form Configuration","slug":"extending-the-form-configuration","link":"#extending-the-form-configuration","children":[]},{"level":3,"title":"Overriding Controller Action","slug":"overriding-controller-action","link":"#overriding-controller-action","children":[]},{"level":3,"title":"Overriding Form Save Data","slug":"overriding-form-save-data","link":"#overriding-form-save-data","children":[]},{"level":3,"title":"Overriding Controller Redirect","slug":"overriding-controller-redirect","link":"#overriding-controller-redirect","children":[]},{"level":3,"title":"Extending Form Model Query","slug":"extending-form-model-query","link":"#extending-form-model-query","children":[]},{"level":3,"title":"Extending Form Fields","slug":"extending-form-fields","link":"#extending-form-fields","children":[]},{"level":3,"title":"Filtering Form Fields","slug":"filtering-form-fields","link":"#filtering-form-fields","children":[]},{"level":3,"title":"Refreshing the Form via AJAX","slug":"refreshing-the-form-via-ajax","link":"#refreshing-the-form-via-ajax","children":[]},{"level":3,"title":"Getting the Active Form Model","slug":"getting-the-active-form-model","link":"#getting-the-active-form-model","children":[]},{"level":3,"title":"Extending Every Form Refresh","slug":"extending-every-form-refresh","link":"#extending-every-form-refresh","children":[]}]},{"level":2,"title":"Validating Form Fields","slug":"validating-form-fields","link":"#validating-form-fields","children":[]}],"relativePath":"3.x/extend/forms/form-controller.md","filePath":"3.x/extend/forms/form-controller.md"}'),i={name:"3.x/extend/forms/form-controller.md"};function u(d,n,k,g,h,m){const t=a("pre-heading"),e=a("post-heading");return p(),l("div",null,[s(t),n[0]||(n[0]=c("h1",null,"Form Controller",-1)),s(e),n[1]||(n[1]=r(`<p>The <code>Backend\\Behaviors\\FormController</code> class is a controller behavior used for easily adding form functionality to a backend page. The behavior provides three pages called Create, Update and Preview. The Preview page is a read-only version of the Update page. When you use the form behavior you don&#39;t need to define the <code>create</code>, <code>update</code> and <code>preview</code> actions in the controller - the behavior does it for you. However you should provide the corresponding view files.</p><p>Form behavior depends on form <a href="./../../element/form-fields.html">field definitions</a> and a <a href="./../database/model.html">model class</a>. In order to use the form behavior you should add it to the <code>$implement</code> property of the controller class. Also, the <code>$formConfig</code> class property should be defined and its value should refer to the YAML file used for configuring the behavior properties.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Categories</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>FormController</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$formConfig</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;config_form.yaml&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="custom-block tip"><p>Very often the form and <a href="./../lists/list-controller.html">list controller</a> are used together in a same controller.</p></div><h2 id="configuring-the-form-behavior"><a href="#configuring-the-form-behavior" class="header-anchor">#</a> Configuring the Form Behavior</h2><p>The configuration file referred in the <code>$formConfig</code> property is defined in YAML format. The file should be placed into the <a href="./../system/views.html">controller&#39;s view directory</a>. Below is an example of a typical form behavior configuration file.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_form.yaml</span>
<span class="token key atrule">name</span><span class="token punctuation">:</span> Blog Category
<span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/blog/models/post/fields.yaml
<span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Blog\\Post

<span class="token key atrule">create</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> New Blog Post

<span class="token key atrule">update</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Edit Blog Post

<span class="token key atrule">preview</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> View Blog Post
</code></pre></div><p>The following properties are required in the form configuration file.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>name</strong></td><td>the name of the object being managed by this form.</td></tr><tr><td><strong>form</strong></td><td>a configuration array or reference to a form field definition file, see <a href="./../../element/form-fields.html">form fields</a>.</td></tr><tr><td><strong>modelClass</strong></td><td>a model class name, the form data is loaded and saved against this model.</td></tr></tbody></table></div><p>The configuration properties listed below are optional. Define them if you want the form behavior to support the Create, Update or Preview pages.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>design</strong></td><td>display the form using a specific form design mode when rendering (see below).</td></tr><tr><td><strong>defaultRedirect</strong></td><td>used as a fallback redirection page when no specific redirect page is defined.</td></tr><tr><td><strong>create</strong></td><td>a configuration array or reference to a config file for the Create page.</td></tr><tr><td><strong>update</strong></td><td>a configuration array or reference to a config file for the Update page.</td></tr><tr><td><strong>preview</strong></td><td>a configuration array or reference to a config file for the Preview page.</td></tr><tr><td><strong>customMessages</strong></td><td>customize the messages used in the Form Controllers.</td></tr><tr><td><strong>permissions</strong></td><td>apply restrictions to certain actions provided by the Form Controller.</td></tr></tbody></table></div><h3 id="create-page"><a href="#create-page" class="header-anchor">#</a> Create Page</h3><p>To support the Create page add the following configuration to the YAML file.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">create</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> New Blog Post
    <span class="token key atrule">redirect</span><span class="token punctuation">:</span> acme/blog/posts/update/<span class="token punctuation">:</span>id
    <span class="token key atrule">redirectClose</span><span class="token punctuation">:</span> acme/blog/posts
</code></pre></div><p>The following properties are supported for the Create page.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>a page title, can refer to a <a href="./../system/localization.html">localization string</a>.</td></tr><tr><td><strong>redirect</strong></td><td>redirection page when record is saved.</td></tr><tr><td><strong>redirectClose</strong></td><td>redirection page when record is saved and the <strong>close</strong> post variable is sent with the request.</td></tr><tr><td><strong>form</strong></td><td>overrides the default form fields definitions for the create page only.</td></tr></tbody></table></div><h3 id="update-page"><a href="#update-page" class="header-anchor">#</a> Update Page</h3><p>To support the Update page add the following configuration to the YAML file.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">update</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Edit Blog Post
    <span class="token key atrule">redirect</span><span class="token punctuation">:</span> acme/blog/posts
</code></pre></div><p>The following properties are supported for the Update page.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>a page title, can refer to a <a href="./../system/localization.html">localization string</a>.</td></tr><tr><td><strong>redirect</strong></td><td>redirection page when record is saved.</td></tr><tr><td><strong>redirectClose</strong></td><td>redirection page when record is saved and <strong>close</strong> post variable is sent with the request.</td></tr><tr><td><strong>form</strong></td><td>overrides the default form fields definitions for the update page only.</td></tr></tbody></table></div><h3 id="preview-page"><a href="#preview-page" class="header-anchor">#</a> Preview Page</h3><p>To support the Preview page add the following configuration to the YAML file:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">preview</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> View Blog Post
</code></pre></div><p>The following properties are supported for the Preview page.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>a page title, can refer to a <a href="./../system/localization.html">localization string</a>.</td></tr><tr><td><strong>form</strong></td><td>overrides the default form fields definitions for the preview page only.</td></tr></tbody></table></div><h3 id="custom-messages"><a href="#custom-messages" class="header-anchor">#</a> Custom Messages</h3><p>Specify the <code>customMessages</code> property to override the default messages used by the Form Controller. The values can be plain text or can refer to a <a href="./../system/localization.html">localization string</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">customMessages</span><span class="token punctuation">:</span>
    <span class="token key atrule">notFound</span><span class="token punctuation">:</span> Did not find the thing
    <span class="token key atrule">flashCreate</span><span class="token punctuation">:</span> New thing created
    <span class="token key atrule">flashUpdate</span><span class="token punctuation">:</span> Updated that thing
    <span class="token key atrule">flashDelete</span><span class="token punctuation">:</span> Thing is gone
</code></pre></div><p>You may also modify messages in the context of the form being displayed. The following will override the <code>notFound</code> message for the <code>update</code> context only.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">update</span><span class="token punctuation">:</span>
    <span class="token key atrule">customMessages</span><span class="token punctuation">:</span>
        <span class="token key atrule">notFound</span><span class="token punctuation">:</span> Nothing found when updating
</code></pre></div><p>The following messages are available to override as custom messages.</p><details class="custom-block details"><summary>View the list of available messages</summary><div class="table"><table tabindex="0"><thead><tr><th>Message</th><th>Default Message</th></tr></thead><tbody><tr><td><strong>notFound</strong></td><td>Form record with an ID of :id could not be found.</td></tr><tr><td><strong>flashCreate</strong></td><td>:name Created</td></tr><tr><td><strong>flashUpdate</strong></td><td>:name Updated</td></tr><tr><td><strong>flashDelete</strong></td><td>:name Deleted</td></tr></tbody></table></div></details><h3 id="restricting-with-permissions"><a href="#restricting-with-permissions" class="header-anchor">#</a> Restricting with Permissions</h3><p>Specify the <code>permissions</code> property to apply restrictions to actions provided by the Form Controller. Use <a href="./../backend/permissions.html">permission values</a> that the current backend user must have in order for the field to be used. Supports either a string for a single permission or an array of permissions of which only one is needed to grant access.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">permissions</span><span class="token punctuation">:</span>
    <span class="token key atrule">modelCreate</span><span class="token punctuation">:</span> admins.manage.create
    <span class="token key atrule">modelDelete</span><span class="token punctuation">:</span> admins.manage.delete
</code></pre></div><p>The following properties are available to override as required permissions.</p><details class="custom-block details"><summary>View the list of available messages</summary><div class="table"><table tabindex="0"><thead><tr><th>Message</th><th>Default Message</th></tr></thead><tbody><tr><td><strong>modelCreate</strong></td><td>required to create new records.</td></tr><tr><td><strong>modelUpdate</strong></td><td>required to modify existing records.</td></tr><tr><td><strong>modelPreview</strong></td><td>required to preview existing records.</td></tr><tr><td><strong>modelDelete</strong></td><td>required to delete existing records.</td></tr></tbody></table></div></details><h2 id="defining-form-fields"><a href="#defining-form-fields" class="header-anchor">#</a> Defining Form Fields</h2><div class="custom-block aside"><p>The available form field properties can be found on the <a href="./../../element/form-fields.html">form field definitions</a> page.</p></div><p>Form fields are defined with the YAML file. The form fields configuration is used by the form behavior for creating the form controls and binding them to the model fields.</p><p>The file is placed to a subdirectory of the <strong>models</strong> directory of a plugin. The subdirectory name matches the model class name written in lowercase. The file name doesn&#39;t matter, but <strong>fields.yaml</strong> and <strong>form_fields.yaml</strong> are common names. Example form fields file location:</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── blog
|           └── <code>models</code>
|               ├── post  <em>← Config Directory</em>
|               |   └── fields.yaml  <em>← Config File</em>
|               └── Post.php  <em>← Model Class</em></p>
</code></pre><p>Fields can be placed in three areas, the <strong>outside area</strong>, <strong>primary tabs</strong> or <strong>secondary tabs</strong>. The next example shows the typical contents of a form fields definition file.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># fields.yaml</span>
<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">blog_title</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Blog Title
        <span class="token key atrule">description</span><span class="token punctuation">:</span> The title for this blog

    <span class="token key atrule">published_at</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Published date
        <span class="token key atrule">description</span><span class="token punctuation">:</span> When this blog post was published
        <span class="token key atrule">type</span><span class="token punctuation">:</span> datepicker

    <span class="token comment"># [...]</span>

<span class="token key atrule">tabs</span><span class="token punctuation">:</span>
    <span class="token key atrule">fields</span><span class="token punctuation">:</span>
        <span class="token comment"># [...]</span>

<span class="token key atrule">secondaryTabs</span><span class="token punctuation">:</span>
    <span class="token key atrule">fields</span><span class="token punctuation">:</span>
        <span class="token comment"># [...]</span>
</code></pre></div><h2 id="form-views"><a href="#form-views" class="header-anchor">#</a> Form Views</h2><p>For each page your form supports Create, Update and Preview you should provide a <a href="./../backend/controllers-ajax.html">view file</a> with the corresponding name - <strong>create.php</strong>, <strong>update.php</strong> and <strong>preview.php</strong>.</p><p>The form behavior adds two methods to the controller class: <code>formRender</code>, <code>formRenderDesign</code> and <code>formRenderPreview</code>. These methods render the form controls configured with the YAML file described above.</p><h3 id="create-view"><a href="#create-view" class="header-anchor">#</a> Create View</h3><p>The <strong>create.php</strong> view represents the Create page that allows users to create new records. A typical Create page contains breadcrumbs, the form itself, and the form buttons. The <strong>data-request</strong> attribute should refer to the <code>onSave</code> AJAX handler provided by the form behavior. Below is a contents of the typical create view file.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;d-flex flex-column h-100&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>flex-grow-1<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formRender</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-buttons<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">data-control</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>loader-container<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
                <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>button<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSave<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request-data</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ close: true }<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request-message</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Creating Category...<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-hotkey</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>ctrl+enter, cmd+enter<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-default<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
                Create and Close
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>span</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn-text<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
                or <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/categories&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Cancel<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>span</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>To track unsaved changes and display a warning when navigating away from the form, include the <code>data-change-monitor</code> attribute on the form opening tag.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;...&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;data-change-monitor&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h3 id="update-view"><a href="#update-view" class="header-anchor">#</a> Update View</h3><p>The <strong>update.php</strong> view represents the Update page that allows users to update or delete existing records. A typical Update page contains breadcrumbs, the form itself, and the form buttons. The Update page is very similar to the Create page, but usually has the Delete button. The <strong>data-request</strong> attribute should refer to the <code>onSave</code> AJAX handler provided by the form behavior. Below is a contents of the typical update.php form.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;d-flex flex-column h-100&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>flex-grow-1<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formRender</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-buttons<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">data-control</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>loader-container<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
                <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>button<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSave<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request-data</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ close: true }<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request-message</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Saving Category...<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-hotkey</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>ctrl+enter, cmd+enter<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-default<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
                Save and Close
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
                <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>button<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>oc-icon-trash-o btn-icon danger pull-right<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onDelete<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request-message</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Deleting Category...<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request-confirm</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Do you really want to delete this category?<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>span</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn-text<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
                or <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/categories&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Cancel<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>span</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h3 id="preview-view"><a href="#preview-view" class="header-anchor">#</a> Preview View</h3><p>The <strong>preview.php</strong> view represents the Preview page that allows users to preview existing records in the read-only mode. A typical Preview page contains breadcrumbs and the form itself. Below is a contents of the typical preview.php form.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-preview<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formRenderPreview</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="form-designs"><a href="#form-designs" class="header-anchor">#</a> Form Designs</h2><p>The <code>create:controller</code> command generates <a href="./../system/controllers.html">a controller</a> and supports the <code>--design</code> option to implement the desired display mode, as described below.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan create:controller Acme.Blog Posts <span class="token parameter variable">--design</span><span class="token operator">=</span>popup
</code></pre></div><p>Form designs are a useful when you need to display the form without managing the HTML contents, which is less flexible but can make the process of building forms faster.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">design</span><span class="token punctuation">:</span>
    <span class="token key atrule">displayMode</span><span class="token punctuation">:</span> basic
</code></pre></div><p>The <strong>design</strong> property, in the behavior configuration, controls how the form is displayed. The following properties are supported.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>displayMode</strong></td><td>specifies the display mode to use, supported values: <code>custom</code>, <code>basic</code>, <code>survey</code>, <code>sidebar</code>, <code>popup</code>. Default: <code>basic</code></td></tr><tr><td><strong>horizontalMode</strong></td><td>show form fields in horizontal orientation. Default: <code>false</code></td></tr><tr><td><strong>surveyMode</strong></td><td>disables tabs and displays all fields on the page in sections with headers. Default: <code>false</code></td></tr><tr><td><strong>size</strong></td><td>size of the page container, supported values: <code>50</code> stepped increments between <code>400</code>-<code>1200</code>, <code>auto</code>. Default: <code>auto</code></td></tr><tr><td><strong>sidebarSize</strong></td><td>width of the sidebar in <code>sidebar</code> mode, supported values <code>50</code> steps between <code>300</code>-<code>750</code>. Default: <code>300</code></td></tr></tbody></table></div><p>Use the <code>formRenderDesign</code> method to render the form design inside the <strong>create.php</strong>, <strong>update.php</strong> and <strong>preview.php</strong> view files.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formRenderDesign</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h3 id="display-modes"><a href="#display-modes" class="header-anchor">#</a> Display Modes</h3><p>When using a <strong>design</strong> display mode in the behavior configuration, the view contents are generated using standard form contents provided by the system.</p><p>The following <strong>displayMode</strong> values are supported with their descriptions.</p><div class="table"><table tabindex="0"><thead><tr><th>Display Mode</th><th>Description</th></tr></thead><tbody><tr><td><strong>custom</strong></td><td>Render the form using custom view files (default)</td></tr><tr><td><strong>basic</strong></td><td>Basic layout with for standard forms</td></tr><tr><td><strong>survey</strong></td><td>Survey layout using stacked sections with headings</td></tr><tr><td><strong>sidebar</strong></td><td>Sidebar layout where secondary tabs are rendered in the side panel</td></tr><tr><td><strong>popup</strong></td><td>Form contents are managed inside popup windows</td></tr></tbody></table></div><p>The <strong>size</strong> property defines the size of the page container or the popup size.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">design</span><span class="token punctuation">:</span>
    <span class="token key atrule">displayMode</span><span class="token punctuation">:</span> survey
    <span class="token key atrule">size</span><span class="token punctuation">:</span> <span class="token number">950</span>
</code></pre></div><h3 id="popup-display-mode"><a href="#popup-display-mode" class="header-anchor">#</a> Popup Display Mode</h3><p>If the <strong>design</strong> is set to use the <code>popup</code> display mode, then you don&#39;t need to create any view files at all. All the form management features are contained inside a popup window.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">design</span><span class="token punctuation">:</span>
    <span class="token key atrule">displayMode</span><span class="token punctuation">:</span> popup
    <span class="token key atrule">size</span><span class="token punctuation">:</span> <span class="token number">750</span>
</code></pre></div><p>When integrated with the <a href="./../lists/list-controller.html">list controller</a>, set the <strong>recordOnClick</strong> property to <code>popup</code> to open the manage view when clicking a record.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_list.yaml</span>
<span class="token key atrule">recordOnClick</span><span class="token punctuation">:</span> popup
</code></pre></div><p>The <strong>recordOnClick</strong> also supports passing a context to the Form Controller, for example, set the value to <code>popup@preview</code> for the preview context.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_list.yaml</span>
<span class="token key atrule">recordOnClick</span><span class="token punctuation">:</span> popup@preview
</code></pre></div><p>The create view can be opened using the <code>onLoadPopupForm</code> AJAX handler in conjunction with the popup control, as in the example below.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>button<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-control</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>popup<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-handler</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onLoadPopupForm<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-primary<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    New Item
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="extending-form-behavior"><a href="#extending-form-behavior" class="header-anchor">#</a> Extending Form Behavior</h2><p>Sometimes you may wish to modify the default form behavior and there are several ways you can do this.</p><h3 id="extending-the-form-configuration"><a href="#extending-the-form-configuration" class="header-anchor">#</a> Extending the Form Configuration</h3><p>You may extend the form configuration dynamically using the <code>formGetConfig</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">formGetConfig</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$config</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">asExtension</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;FormController&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">formGetConfig</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$config</span><span class="token operator">-&gt;</span><span class="token property">form</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makeConfig</span><span class="token punctuation">(</span><span class="token variable">$config</span><span class="token operator">-&gt;</span><span class="token property">form</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Set the active tab dynamically</span>
    <span class="token variable">$config</span><span class="token operator">-&gt;</span><span class="token property">form</span><span class="token operator">-&gt;</span><span class="token property">tabs</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;activeTab&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Activities&#39;</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token variable">$config</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="overriding-controller-action"><a href="#overriding-controller-action" class="header-anchor">#</a> Overriding Controller Action</h3><p>You may use your own logic for the <code>create</code>, <code>update</code> or <code>preview</code> action method in the controller, then optionally call the Form behavior parent method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">update</span><span class="token punctuation">(</span><span class="token variable">$recordId</span><span class="token punctuation">,</span> <span class="token variable">$context</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">//</span>
    <span class="token comment">// Do any custom code here</span>
    <span class="token comment">//</span>

    <span class="token comment">// Call the FormController behavior update() method</span>
    <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">asExtension</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;FormController&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">update</span><span class="token punctuation">(</span><span class="token variable">$recordId</span><span class="token punctuation">,</span> <span class="token variable">$context</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="overriding-form-save-data"><a href="#overriding-form-save-data" class="header-anchor">#</a> Overriding Form Save Data</h3><p>You may use the <code>formBeforeSave</code> override (or equivalent) to change the save values of the form before it is saved or updated. To override the save value of a field use the <code>formSetSaveValue(key, value)</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">formBeforeSave</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// When locale dropdown is set to &quot;custom&quot;, override with the _custom_locale text field</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;MyModel[locale]&#39;</span><span class="token punctuation">)</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;custom&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formSetSaveValue</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;locale&#39;</span><span class="token punctuation">,</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;MyModel[_custom_locale]&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="overriding-controller-redirect"><a href="#overriding-controller-redirect" class="header-anchor">#</a> Overriding Controller Redirect</h3><p>You can specify the URL to redirect to after the model is saved by overriding the <code>formGetRedirectUrl</code> method. This method returns the location to redirect to with relative URLs being treated as backend URLs.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">formGetRedirectUrl</span><span class="token punctuation">(</span><span class="token variable">$context</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">,</span> <span class="token variable">$model</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;https://octobercms.com&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="extending-form-model-query"><a href="#extending-form-model-query" class="header-anchor">#</a> Extending Form Model Query</h3><p>The lookup query for the form <a href="./../database/model.html">database model</a> can be extended by overriding the <code>formExtendQuery</code> method inside the controller class. This example will ensure that soft deleted records can still be found and updated, by applying the <strong>withTrashed</strong> scope to the query:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">formExtendQuery</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">withTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="extending-form-fields"><a href="#extending-form-fields" class="header-anchor">#</a> Extending Form Fields</h3><p>You may extend the fields of another controller from outside by binding to the <code>backend.form.extendFields</code> <a href="./../services/event.html">global event</a>. The event function will take a <code>$form</code> argument that represents the <code>Backend\\Widgets\\Form</code> object, where you can use the <code>getController</code>, <code>getModel</code> and <code>getContext</code> methods to check the execution context.</p><p>Since this event has the potential to affect all forms, it is essential to check that the controller and model is of the correct type. Here is an example using the <code>addFields</code> method to add new fields to the mail settings form.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.form.extendFields&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$form</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>
        <span class="token operator">!</span><span class="token variable">$form</span><span class="token operator">-&gt;</span><span class="token function">getController</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Controllers<span class="token punctuation">\\</span>Settings</span> <span class="token operator">||</span>
        <span class="token operator">!</span><span class="token variable">$form</span><span class="token operator">-&gt;</span><span class="token function">getModel</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>MailSetting</span>
    <span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token variable">$form</span><span class="token operator">-&gt;</span><span class="token function">addFields</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;my_field&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;My Field&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;comment&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;This is a custom field I have added.&#39;</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You can also extend the form fields internally by overriding the <code>formExtendFields</code> method inside the controller class. This will only affect the form used by the <code>FormController</code> behavior.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Categories</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>FormController</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">formExtendFields</span><span class="token punctuation">(</span><span class="token variable">$form</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$form</span><span class="token operator">-&gt;</span><span class="token function">addFields</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The following methods are available on the <code>$form</code> object.</p><div class="table"><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><strong>addFields</strong></td><td>adds new fields to the outside area</td></tr><tr><td><strong>addTabFields</strong></td><td>adds new fields to the tabbed area</td></tr><tr><td><strong>addSecondaryTabFields</strong></td><td>adds new fields to the secondary tabbed area</td></tr><tr><td><strong>removeField</strong></td><td>remove a field from any areas</td></tr></tbody></table></div><p>Each method takes an array of fields similar to the <a href="./../../element/form-fields.html">form field configuration</a>.</p><h3 id="filtering-form-fields"><a href="#filtering-form-fields" class="header-anchor">#</a> Filtering Form Fields</h3><p>As described in the <a href="./field-dependencies.html">field dependencies section</a>, you may also implement form field filtering by extension by hooking in to the <code>form.filterFields</code> event.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.form.filterFields&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$formWidget</span><span class="token punctuation">,</span> <span class="token variable">$fields</span><span class="token punctuation">,</span> <span class="token variable">$context</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">source_type</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;http&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">source_url</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
            <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">git_branch</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
        <span class="token keyword">elseif</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">source_type</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;git&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">source_url</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
            <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">git_branch</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
        <span class="token keyword">else</span> <span class="token punctuation">{</span>
            <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">source_url</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
            <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">git_branch</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="refreshing-the-form-via-ajax"><a href="#refreshing-the-form-via-ajax" class="header-anchor">#</a> Refreshing the Form via AJAX</h3><p>When a custom AJAX handler needs to update all form fields at once, use the form widget&#39;s <code>onRefresh</code> method. This re-renders the entire form and returns the result as a DOM update array, which the AJAX framework applies automatically.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onMyAction</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// ... your logic ...</span>

    <span class="token comment">// Re-renders all form fields, tabs and custom partials in one request</span>
    <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formGetWidget</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">onRefresh</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>To refresh the form and one or more relation containers simultaneously, merge the results:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onMyAction</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// ... your logic ...</span>

    <span class="token keyword">return</span> <span class="token function">array_merge</span><span class="token punctuation">(</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formGetWidget</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">onRefresh</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment">// all form fields</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">relationRefresh</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;files&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>       <span class="token comment">// a specific relation</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">relationRefresh</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;comments&#39;</span><span class="token punctuation">)</span>     <span class="token comment">// another relation</span>
    <span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><blockquote><p><strong>Note:</strong> If your relation fields are declared directly inside <code>config_form.yaml</code> as <code>type: relation</code>, they are part of the form widget and will be refreshed by <code>formGetWidget()-&gt;onRefresh()</code> automatically. Use <code>relationRefresh()</code> only for relations managed by <code>RelationController</code> (declared in <code>config_relation.yaml</code>).</p></blockquote><h3 id="getting-the-active-form-model"><a href="#getting-the-active-form-model" class="header-anchor">#</a> Getting the Active Form Model</h3><p>The <code>formGetModel</code> method returns the model currently bound to the form. This is especially useful in custom AJAX handlers where the form is open in a popup and the model is already initialised by the behavior — avoiding the need to re-query the database using <code>post(&#39;record_id&#39;)</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onMyAction</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$model</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formGetModel</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">status</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;processed&#39;</span><span class="token punctuation">;</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formGetWidget</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">onRefresh</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="extending-every-form-refresh"><a href="#extending-every-form-refresh" class="header-anchor">#</a> Extending Every Form Refresh</h3><p>The <code>formExtendRefreshResults</code> override is called automatically on every <code>onRefresh</code> cycle, including calls triggered by field dependencies or <code>formGetWidget()-&gt;onRefresh()</code>. Use it to inject additional DOM updates into any refresh without modifying individual AJAX handlers.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">formExtendRefreshResults</span><span class="token punctuation">(</span><span class="token variable">$host</span><span class="token punctuation">,</span> <span class="token variable">$result</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$model</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formGetModel</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Appended to every refresh response automatically</span>
    <span class="token keyword">return</span> <span class="token variable">$result</span> <span class="token operator">+</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;#my-status-block&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makePartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;status_block&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;model&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$model</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>This is the inverse of <code>formGetWidget()-&gt;onRefresh()</code>: instead of triggering a full refresh manually, you declare what should always be appended whenever a refresh occurs.</p><h2 id="validating-form-fields"><a href="#validating-form-fields" class="header-anchor">#</a> Validating Form Fields</h2><p>To validate the fields of your form you can make use of the <a href="./../database/traits.html">Validation trait</a> in your model.</p>`,127))])}const y=o(i,[["render",u]]);export{v as __pageData,y as default};
